from pathlib import Path
s=Path('scripts/criar-vd-explica-m3-d1.py').read_text(encoding='utf-8-sig')
s=s.replace("OUT=ROOT/'assets/videos/missao-3/desafio-1/vd-explica-m3-d1'","OUT=ROOT/'assets/videos/missao-3/desafio-1/vd-explica-m3-d1-resolvido'")
s=s.replace("('fim',5,'Agora é a sua vez! Resolva o desafio e confira se a soma dos três lados é sempre cinco. Boa sorte, pequenos matemáticos!')","('parabens',5,'Parabéns! Você conseguiu! Com o três no topo e no meio da base, todos os lados somam cinco! Muito bem, pequeno matemático! Agora é a sua vez de praticar!')")
s=s.replace("'testar','fim'","'testar','parabens'")
s=s.replace("VALUES=[1,1,1,1,3,3]","VALUES=[1,1,1,1,3,3]\nTOKEN_ORDER=[4,0,1,2,5,3]\nSOLUTION={j:VALUES[token] for j,token in enumerate(TOKEN_ORDER)}\nassert all(sum(SOLUTION[i] for i in side)==5 for side in SIDES)")
s=s.replace("who='boy' if k in ['duvida','testar'] else 'teacher'","who='happy' if k=='testar' and t>8 else 'boy' if k in ['duvida','testar'] else 'teacher'")
s=s.replace("'Sua vez!' if k=='fim'","'Parabéns! Você conseguiu!' if k=='parabens'")
s=s.replace("for j in range(6):\n   begin=start+j*1.15\n   if t>=begin+1:filled[j]=VALUES[j];used.add(j)\n   elif t>=begin:used.add(j);moving=(j,j,t-begin)","for j,token in enumerate(TOKEN_ORDER):\n   begin=start+j*1.15\n   if t>=begin+1:filled[j]=VALUES[token];used.add(token)\n   elif t>=begin:used.add(token);moving=(token,j,t-begin)")
s=s.replace(" triangle(d,filled,highlight)"," if k=='parabens':\n  filled=SOLUTION.copy();used=set(range(6));highlight=int(t/1.5)%3\n triangle(d,filled,highlight)")
s=s.replace("text(d,855,533,'NÚMEROS DISPONÍVEIS',18,TEAL)","text(d,855,533,'TODOS OS NÚMEROS UTILIZADOS' if len(used)==6 and not moving else 'NÚMEROS DISPONÍVEIS',18,TEAL)")
s=s.replace("if k=='testar' and len(filled)==6:","if k in ['testar','parabens'] and len(filled)==6:")
s=s.replace("'TENTATIVA — CONFIRA!'","'DESAFIO RESOLVIDO!'").replace("'Ainda não! Troque os números.'","'Os três lados somam cinco!'")
s=s.replace("  text(d,232,583,'Os três lados somam cinco!',21,TEAL)","  text(d,232,583,'Os três lados somam cinco!',21,TEAL)\n  side=SIDES[highlight if highlight is not None else 0]\n  equation=' + '.join(str(filled[i]) for i in side)+' = 5'\n  text(d,855,579,equation,35,TEAL)")
s=s.replace("caption='Observe os três lados. Cada um precisa somar 5.' if k!='testar' else 'Teste, confira os três lados e mude os números de lugar.'","caption='Muito bem! Os três lados somam 5.' if k=='parabens' or k=='testar' and len(filled)==6 else 'Observe os três lados. Cada um precisa somar 5.'")
s=s.replace("('fim',3)","('parabens',3)")
Path('scripts/criar-vd-explica-m3-d1-resolvido.py').write_text(s,encoding='utf-8')
